#!/usr/bin/env python3
"""Create standalone GitHub Pages docs from Markdown. No external CDN required."""
from pathlib import Path
from html import escape
from re import sub
from shutil import copyfile
from markdown_it import MarkdownIt

ROOT=Path(__file__).resolve().parents[1]
DOCS=ROOT/'docs'
DOC_ASSETS=DOCS/'assets';DOC_ASSETS.mkdir(exist_ok=True)
ORDER=[
 ('index','Overview','README.md'),
 ('quick-start','Quick start','docs/QUICK_START.md'),
 ('developer-api','Developer C/C++ API','docs/DEVELOPER_API.md'),
 ('categories','Categories & templates','docs/CUSTOM_CATEGORIES_AND_TEMPLATES.md'),
 ('custom-title','Custom title & styling','docs/CUSTOM_TITLE.md'),
 ('single-hud-button','HUD button & editor','docs/FIX_SINGLE_HUD_BUTTON.md'),
 ('web','HTML, CSS & JavaScript','docs/WEB_MENU_DEVELOPMENT.md'),
 ('design','Design & scaling','docs/DESIGN_AND_RESOLUTION.md'),
 ('startup','Android & startup','docs/ANDROID_DEX_AUTOSTART.md'),
 ('troubleshooting','Troubleshooting','docs/FIX_STARTUP_WORLD_OVERLAY.md'),
 ('compatibility','Compatibility','docs/COMPATIBILITY_AND_TESTING.md'),
 ('github-pages','GitHub Pages setup','docs/GITHUB_PAGES.md'),
]
STYLE=r'''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0d121a;color:#dbe6ee;font:15px/1.65 system-ui,-apple-system,'Segoe UI',sans-serif}a{color:#6bd2ed;text-decoration:none}a:hover{text-decoration:underline}.shell{display:flex;min-height:100vh}.sidebar{width:280px;position:sticky;top:0;height:100vh;flex-shrink:0;overflow-y:auto;border-right:1px solid #263443;background:#111923;padding:24px 17px}.identity{display:flex;gap:12px;align-items:center;padding:10px 8px 28px}.identity img{width:45px;height:45px;object-fit:contain}.identity strong{font:900 22px Impact,'Arial Narrow',sans-serif;letter-spacing:.1px}.identity small{display:block;color:#88a2af;font-size:11px}.navcaption{font-size:11px;font-weight:700;color:#7893a4;letter-spacing:.15em;margin:17px 12px 7px}.side-link{display:flex;gap:9px;align-items:center;color:#a8c2ce;border-radius:7px;padding:9px 10px;font-size:13px}.side-link b{color:#627f90;font-size:11px}.side-link:hover,.side-link.active{background:#1e3749;color:white;text-decoration:none}.side-link.active{border-left:3px solid #26b5da}.search{background:#0b1118;border:1px solid #344556;color:#fff;border-radius:8px;padding:9px;width:100%;font-size:13px}.sidebar-footer{border-top:1px solid #2b3b47;margin-top:25px;padding:20px 12px 10px;font-size:12px}.main{flex:1;min-width:0}.topbar{height:66px;border-bottom:1px solid #243342;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(20px,5vw,80px);position:sticky;top:0;background:#0d121aee;backdrop-filter:blur(12px);z-index:2;color:#89a8b8;font-size:12px}.topbar span{color:#55cde8}.topbar a{margin-left:18px}.article{max-width:1030px;margin:auto;padding:42px clamp(20px,5vw,75px) 90px}.eyebrow{font-size:11px;color:#58c9e7;letter-spacing:.15em;font-weight:800}.article h1,.article h2,.article h3{line-height:1.25;color:#f8fbfd}.article h1{font-size:clamp(28px,4vw,42px);margin:12px 0 22px}.article h2{font-size:24px;margin-top:34px;border-top:1px solid #223443;padding-top:24px}.article h3{font-size:18px;margin-top:25px}.article p,.article ul,.article ol{color:#b8c9d3}.article code{color:#91e9ff;background:#1c2733;padding:2px 5px;border-radius:4px;font:12px/1.4 ui-monospace,'SFMono-Regular',Consolas,monospace}.article pre{background:#101f2a;border:1px solid #2a4552;border-radius:9px;overflow:auto;padding:17px;position:relative}.article pre code{background:none;padding:0;font-size:12px;line-height:1.6;white-space:pre}.article blockquote{border-left:3px solid #25acd4;background:#152a36;padding:9px 19px;margin:20px 0}.article table{border-collapse:collapse;display:block;max-width:100%;overflow-x:auto}.article td,.article th{border:1px solid #35495a;padding:9px 11px;text-align:left;min-width:90px}.article th{background:#193141;color:#f5fcff}.article img{max-width:100%;height:auto;border:1px solid #2d4455;border-radius:10px}.article hr{border:0;border-top:1px solid #273b49;margin:32px 0}.jump{margin-top:36px;border-top:1px solid #2b3e50;padding-top:24px;display:flex;justify-content:space-between;gap:18px;font-size:13px}.note{color:#8fa7b5;font-size:12px;margin-top:15px}.copy{position:absolute;right:10px;top:10px;border:1px solid #416176;border-radius:4px;background:#213a48;color:#d5f2fb;font-size:11px;padding:4px 9px;cursor:pointer}#mob{display:none}#empty{color:#9fb9c9;font-size:12px;margin:10px} @media(max-width:800px){#mob{display:block;position:fixed;z-index:15;top:13px;left:12px;border:1px solid #3a667e;background:#14344b;color:white;border-radius:5px;font-size:20px;padding:6px 12px}.sidebar{position:fixed;left:0;z-index:12;transform:translateX(-102%);transition:transform .15s;box-shadow:10px 0 45px #000a}.nav-open .sidebar{transform:none}.topbar{padding-left:65px}.article{padding-top:30px}.topbar a{margin-left:7px}}'''
JS=r'''(() => {const b=document.getElementById('mob');b.onclick=()=>document.body.classList.toggle('nav-open'); const s=document.getElementById('docSearch'),links=[...document.querySelectorAll('.side-link')],empty=document.getElementById('empty');s.oninput=()=>{const q=s.value.trim().toLowerCase();let found=0;for(const link of links){const hit=link.innerText.toLowerCase().includes(q);link.hidden=!hit;if(hit)found++;}empty.hidden=found>0;};document.querySelectorAll('pre').forEach(el=>{const btn=document.createElement('button');btn.className='copy';btn.textContent='Copy';btn.onclick=()=>{const data=el.querySelector('code').textContent;navigator.clipboard?.writeText(data).then(()=>{btn.textContent='Copied';setTimeout(()=>btn.textContent='Copy',1300);});};el.append(btn);});})();'''
(DOC_ASSETS/'site.css').write_text(STYLE,encoding='utf-8')
(DOC_ASSETS/'site.js').write_text(JS,encoding='utf-8')
copyfile(ROOT/'assets/badlion_logo.png',DOC_ASSETS/'badlion_logo.png')
copyfile(ROOT/'previews/Normal_Mode_Preview_v1.1.5.png',DOC_ASSETS/'menu_preview.png')
(DOCS/'.nojekyll').write_text('')
md=MarkdownIt('default',{'html':False,'linkify':False,'typographer':True})
for i,(slug,name,path) in enumerate(ORDER):
  source=(ROOT/path).read_text(encoding='utf-8')
  article=md.render(source)
  article=sub(r'(?<=\")docs/([A-Za-z0-9_]+)\.md(?=\")',lambda m: {'DEVELOPER_API':'developer-api','QUICK_START':'quick-start','WEB_MENU_DEVELOPMENT':'web','CUSTOM_CATEGORIES_AND_TEMPLATES':'categories','DESIGN_AND_RESOLUTION':'design','COMPATIBILITY_AND_TESTING':'compatibility','GITHUB_PAGES':'github-pages','ANDROID_DEX_AUTOSTART':'startup','FIX_STARTUP_WORLD_OVERLAY':'troubleshooting','CUSTOM_TITLE':'custom-title','FIX_SINGLE_HUD_BUTTON':'single-hud-button'}.get(m.group(1),m.group(1).lower())+'.html',article)
  article=article.replace('src="previews/Normal_Mode_Preview_v1.1.5.png"','src="assets/menu_preview.png"')
  nav=''.join(f'<a class="side-link {"active" if slug==current else ""}" href="{current}.html"><b>{n:02}</b> {escape(label)}</a>' for n,(current,label,_src) in enumerate(ORDER,1))
  back=f'<a href="{ORDER[i-1][0]}.html">← {escape(ORDER[i-1][1])}</a>' if i else '<span></span>'
  forward=f'<a href="{ORDER[i+1][0]}.html">{escape(ORDER[i+1][1])} →</a>' if i<len(ORDER)-1 else '<span></span>'
  doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="BadlionMenuUI native C++ / HTML documentation: {escape(name)}"><title>{escape(name)} — BadlionMenuUI Docs</title><link rel="stylesheet" href="assets/site.css"></head><body><button id="mob" aria-label="Toggle docs navigation">☰</button><div class="shell"><aside class="sidebar"><div class="identity"><img src="assets/badlion_logo.png" alt="Badlion-style logo"><div><strong>BadlionMenuUI</strong><small>C/C++ · Java/DEX · v1.1.5</small></div></div><input id="docSearch" class="search" type="search" placeholder="Filter documentation…" aria-label="Filter documentation links"><div class="navcaption">DEVELOPER DOCUMENTATION</div><nav>{nav}</nav><p id="empty" hidden>No matching page</p><div class="sidebar-footer"><a href="https://github.com/RealBatu20/BadlionClientUILibrary">GitHub repository</a><div class="note">Independent community UI library.</div></div></aside><main class="main"><header class="topbar"><div>BADLIONMENUUI / <span>{escape(name).upper()}</span></div><div><a href="https://github.com/RealBatu20/BadlionClientUILibrary">Source</a><a href="https://github.com/RealBatu20/BadlionClientUILibrary/issues">Issues</a></div></header><div class="article"><div class="eyebrow">MINECRAFT BEDROCK · ANDROID ARM64 · LEVILAUNCHROID</div><article>{article}</article>{('<img src="assets/menu_preview.png" alt="Normal mode template menu">' if i==0 else '')}<div class="jump">{back}{forward}</div><div class="note">v1.1.5 · Native device compatibility not validated for this release.</div></div></main></div><script defer src="assets/site.js"></script></body></html>'''
  target=DOCS/(slug+'.html');target.write_text(doc,encoding='utf-8')
  print(target.relative_to(ROOT),target.stat().st_size)
print('Generated docs pages:',len(ORDER))
